def generate_sequence(x1, x2, max_length=10):
    """
    Generates the sequence x3, x4, ... based on the recurrence relation:
    (x_{i+1} + 1)(x_{i-1} + 1) = x_i^2 + 1
    x_{i+1} = (x_i^2 + 1) / (x_{i-1} + 1) - 1
    Returns the sequence (list of integers) and its length n.
    """
    sequence = [x1, x2]

    for i in range(2, max_length):
        # Calculate x_{i+1} using x_i and x_{i-1}
        xi = sequence[i-1]
        ximinus1 = sequence[i-2]

        numerator = xi**2 + 1
        denominator = ximinus1 + 1

        if numerator % denominator != 0:
            # Not an integer
            return sequence, len(sequence)

        x_next = (numerator // denominator) - 1

        if x_next <= 0:
            # Not a positive integer
            return sequence, len(sequence)

        sequence.append(x_next)

    return sequence, len(sequence)

